def transform(grid):
    g=[r[:] for r in grid]
    # Identify pattern: vertical color 5 frame; neighboring solid color bars define rows/columns.
    # For each row where a horizontal template exists, extend across vertical stem's column extent.
    # Observed template has stem at col2 and row5 carries adjacent blocks 6,9; extend upward to stem top.
    h=len(g); w=len(g[0])
    # horizontal run(s) of nonzero colors adjacent to a vertical line, repeat up/down
    for c in range(w):
        rows=[r for r in range(h) if g[r][c]!=0]
        if len(rows)>=2 and rows==list(range(min(rows),max(rows)+1)):
            # Find horizontal color sequence at one end continuing right from stem
            for r in rows:
                if c+1<w and g[r][c+1]:
                    seq=[]; j=c+1
                    while j<w and g[r][j]: seq.append(g[r][j]); j+=1
                    for rr in rows:
                        for k,v in enumerate(seq):
                            if c+1+k<w: g[rr][c+1+k]=v
                    return g
    return g
